    juce::TextButton editSamples{"EDIT SAMPLES"},detectShotPitch{"DETECT PITCH"};class MappingWindow:public juce::DialogWindow{public:MappingWindow():DialogWindow("Slice Groups - Multi",juce::Colour(0xff282828),true){setUsingNativeTitleBar(true);setResizable(false,false);}void closeButtonPressed()override{if(auto* mapping=dynamic_cast<MultiEditor*>(getContentComponent()))mapping->pause();setVisible(false);}};std::unique_ptr<MappingWindow> multiWindow;bool multiImportBusy=false;
    void openMultiEditor(){if(!p.multiMode)return;if(multiWindow){if(auto* panel=dynamic_cast<MultiEditor*>(multiWindow->getContentComponent()))panel->resume();multiWindow->setVisible(true);multiWindow->toFront(true);return;}auto safe=SafePointer<Editor>(this);auto panel=std::make_unique<MultiEditor>(p,[safe](juce::Array<juce::File> files){if(safe)safe->importMultiFiles(files,true);},[safe](int index){if(safe)safe->detectMultiPitch(index);},[safe]{if(safe&&safe->multiWindow)safe->multiWindow->closeButtonPressed();});panel->setLookAndFeel(&look);multiWindow=std::make_unique<MappingWindow>();multiWindow->setContentOwned(panel.release(),true);multiWindow->centreAroundComponent(this,multiWindow->getWidth(),multiWindow->getHeight());multiWindow->setAlwaysOnTop(true);multiWindow->setVisible(true);}
    void importMultiFiles(juce::Array<juce::File> files,bool append){if(multiImportBusy){tell("Samples are still importing...");return;}multiImportBusy=true;loader.cancel();uint64_t token=++p.loadGeneration;auto safe=SafePointer<Editor>(this);tell("Importing samples and detecting root notes...");browserEditPool.addJob([safe,files,append,token]{if(!safe)return;bool ok=safe->p.importMulti(files,append,token);juce::MessageManager::callAsync([safe,ok]{if(!safe)return;safe->multiImportBusy=false;safe->refresh();safe->resized();safe->tell(ok?"Samples imported. Roots map from filenames or detected pitch; uncertain roots need review.":"Import cancelled or a sample could not be read.");if(ok&&(!safe->multiWindow||!safe->multiWindow->isVisible()))safe->openMultiEditor();});});}
    void detectMultiPitch(int index){auto rows=p.multiRows();if(!juce::isPositiveAndBelow(index,(int)rows.size()))return;auto source=rows[index].source;auto revision=p.configRevision;auto safe=SafePointer<Editor>(this);tell("Detecting sample pitch...");browserEditPool.addJob([safe,source,index,revision]{auto result=SamplePitch::cached(juce::File(source->path),source->buffer,source->rate,true);juce::MessageManager::callAsync([safe,result,source,index,revision]{if(!safe)return;if(safe->p.configRevision!=revision){safe->tell("Pitch result ignored because the mapping changed.");return;}if(result.note<0){safe->tell("Pitch is uncertain; set the root manually.");return;}safe->p.editMulti(index,[&](auto& r){r.root=result.note;r.pitchConfidence=result.confidence;r.pitchMethod="Audio";});safe->tell("Detected "+SamplePitch::name(result.note)+".");});});}
    void detectPitchFiles(juce::Array<juce::File> targets,bool force=true){auto safe=SafePointer<Editor>(this);auto identity=p.getAudio();auto serial=p.loadGeneration.load();tell("Detecting pitch in background...");browserEditPool.addJob([safe,targets,force,identity,serial]{int detected=0,uncertain=0;for(auto file:targets){if(!safe)return;if(file.isDirectory()||file.hasFileExtension("sfz;sgmulti"))continue;auto data=identity&&identity->path==file.getFullPathName()?identity:safe->p.readAudio(file);if(!data)continue;auto result=SamplePitch::cached(file,data->buffer,data->rate,force);if(result.note<0){++uncertain;continue;}++detected;
       if(LibraryStore::playbackType(file)==1&&LibraryStore::editable(file)){Processor temp(false);temp.autoSave=false;if(temp.installAudio(data,true,0,false)){temp.shotRootNote=result.note;temp.loopKey=result.note%12;temp.shotPitchMethod="Audio";temp.shotPitchConfidence=result.confidence;temp.saveLoop();}}
       juce::MessageManager::callAsync([safe,identity,serial,file,result]{if(!safe)return;const juce::ScopedLock g(safe->p.lock);if(safe->p.audio==identity&&identity&&identity->path==file.getFullPathName()&&safe->p.loadGeneration==serial&&safe->p.oneShotMode&&!safe->p.multiMode){safe->p.shotRootNote=result.note;safe->p.loopKey=result.note%12;safe->p.shotPitchConfidence=result.confidence;safe->p.shotPitchMethod="Audio";safe->p.edited(false);safe->refresh();}});
      }juce::MessageManager::callAsync([safe,detected,uncertain]{if(safe){safe->tell("Pitch detected for "+juce::String(detected)+" samples"+(uncertain?"; "+juce::String(uncertain)+" uncertain":""));safe->requestMetadataRefresh();}});});}
    void saveMultiDialog(){if(!p.audio)return;auto file=juce::File(p.audio->path);if(!file.hasFileExtension("sgmulti"))file=file.getSiblingFile(file.getFileNameWithoutExtension()+".sgmulti");chooser=std::make_unique<juce::FileChooser>("Save Multi instrument",file,"*.sgmulti",true);auto safe=SafePointer<Editor>(this);chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe](const juce::FileChooser& dialog){if(!safe||dialog.getResult()==juce::File())return;auto file=dialog.getResult().withFileExtension("sgmulti");safe->tell("Saving Multi instrument...");safe->browserEditPool.addJob([safe,file]{if(!safe)return;bool ok=safe->p.saveMulti(file);juce::MessageManager::callAsync([safe,ok]{if(safe){safe->tell(ok?"Multi instrument saved. Source audio and SFZ unchanged.":"Could not save Multi instrument.");safe->refresh();safe->scanFolder(true,false);}});});});}
    void multiControlVisibility(){if(!p.multiMode&&multiWindow&&multiWindow->isVisible())multiWindow->closeButtonPressed();editSamples.setVisible(p.multiMode);detectShotPitch.setVisible(p.oneShotMode&&!p.multiMode);if(p.multiMode){editSamples.setBounds(shotLoopButton.getX(),shotLoopButton.getY(),130,25);for(auto* c:std::vector<juce::Component*>{&shotLoopButton,&shotZeroButton,&shotNoteButton,&shotNoteHalf,&shotNoteTwice,&shotLoopMode,&shotLoopRelease,&shotGain,&shotGainLabel,&shotBendRange,&shotBendLabel})if(c!=&shotGain&&c!=&shotGainLabel&&c!=&shotBendRange&&c!=&shotBendLabel)c->setVisible(false);for(auto& c:shotBounds)c.setVisible(false);for(auto& c:shotBoundLabels)c.setVisible(false);shotPolyButton.setBounds(editSamples.getRight()+8,editSamples.getY(),66,25);shotLegatoButton.setBounds(shotPolyButton.getRight()+6,editSamples.getY(),76,25);for(auto& c:shotLoopKnobs)c.setVisible(false);for(auto& c:shotLoopLabels)c.setVisible(false);for(auto* c:std::vector<juce::Component*>{&shotFilterCutoff,&shotFilterCutoffLabel,&shotFilterAudition,&shotFilterSlope,&shotTravelKnob,&shotTravelLabel})c->setVisible(false);sourceKey.setVisible(false);wave.shotEditing=false;wave.slicesVisible=false;}else if(p.oneShotMode){detectShotPitch.setVisible(sourceKey.getRight()+124<getWidth());detectShotPitch.setBounds(sourceKey.getRight()+8,sourceKey.getY(),108,24);sourceKey.setTooltip("Root pitch: "+(p.shotRootNote>=0?SamplePitch::name(p.shotRootNote):juce::String("Unknown"))+" · "+p.shotPitchMethod);}}

    void melodicSlices(){if(multiImportBusy||!p.audio)return;std::shared_ptr<const AudioData> source;std::vector<Slice> slices;int begin,end,start;double bpm;{const juce::ScopedLock guard(p.lock);source=p.audio;slices=p.slices;begin=p.regionStart();end=p.regionEnd();start=p.startMarker;bpm=p.sourceBpm;}if((end-begin)/source->rate>120){tell("Choose a loop of up to two minutes.");return;}multiImportBusy=true;auto generation=p.loadGeneration.load();auto safe=SafePointer<Editor>(this);tell("Analysing melodic slices...");browserEditPool.addJob([safe,source,slices,begin,end,start,bpm,generation]{auto cancel=[&]{return !safe||safe->p.loadGeneration!=generation;};auto result=std::make_shared<Processor::MelodicSlices>(Processor::analyseMelodicSlices(source,slices,begin,end,start,bpm,cancel));juce::MessageManager::callAsync([safe,result,generation]{if(!safe)return;safe->multiImportBusy=false;if(safe->p.loadGeneration!=generation)return;int count=(int)result->rows.size(),unknown=result->uncertain;if(safe->p.installMelodicSlices(std::move(*result))){safe->refresh();safe->resized();safe->tell("Created melodic Multi: "+juce::String(count)+" slices"+(unknown?"; "+juce::String(unknown)+" unpitched slices skipped":"")+". Original timing retained in sequencer.");safe->openMultiEditor();}else safe->tell("No confident pitches found in the selected slices.");});});}
